import { test, expect } from '@playwright/test';

test.describe('Logout functionality from side menu', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  test.beforeEach(async ({ page }) => {
    // Navigate to login page
    await page.goto(BASE_URL);

    // Fill in login credentials
    await page.getByLabel('Username').fill(USERNAME);
    await page.getByLabel('Password').fill(PASSWORD);

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for products page to load
    await page.waitForURL(`${BASE_URL}/inventory.html`);
    await expect(page.getByText('Products')).toBeVisible();
  });

  test('should open side menu when burger menu button is clicked', async ({ page }) => {
    // Click the burger menu button
    await page.locator('#react-burger-menu-btn').click();

    // Verify the side menu is visible
    const sideMenu = page.locator('.bm-menu');
    await expect(sideMenu).toBeVisible();

    // Verify logout link is present in the menu
    await expect(page.locator('#logout_sidebar_link')).toBeVisible();
  });

  test('should logout successfully and return to login page', async ({ page }) => {
    // Click the burger menu button
    await page.locator('#react-burger-menu-btn').click();

    // Wait for side menu to be visible
    await expect(page.locator('.bm-menu')).toBeVisible();

    // Click the logout link
    await page.locator('#logout_sidebar_link').click();

    // Verify we're back on the login page
    await page.waitForURL(`${BASE_URL}/`);

    // Verify login button is visible
    await expect(page.getByTestId('login-button')).toBeVisible();

    // Verify we're on the login page by checking for username input
    await expect(page.getByLabel('Username')).toBeVisible();
  });

  test('should not be able to access inventory page after logout', async ({ page }) => {
    // Click the burger menu button
    await page.locator('#react-burger-menu-btn').click();

    // Click the logout link
    await page.locator('#logout_sidebar_link').click();

    // Wait for redirect to login page
    await page.waitForURL(`${BASE_URL}/`);

    // Try to navigate directly to inventory page
    await page.goto(`${BASE_URL}/inventory.html`);

    // Should be redirected back to login page
    await page.waitForURL(`${BASE_URL}/`);

    // Verify login button is visible
    await expect(page.getByTestId('login-button')).toBeVisible();
  });
});
